css:
.mathbiz-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #e8eaf6 0%, #e3f2fd 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.mathbiz-sim-header {
    background: linear-gradient(135deg, #1a237e 0%, #283593 50%, #0d47a1 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 20px;
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
    text-align: center;
}

.mathbiz-sim-header h1 { margin: 0 0 5px 0; font-size: 1.8rem; }
.mathbiz-sim-header p { margin: 0; opacity: 0.9; font-size: 0.95rem; }

.mathbiz-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #555;
}

.mathbiz-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 20px;
}

.mathbiz-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 18px 14px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.2s ease;
}

.mathbiz-sim-status-card:hover { transform: translateY(-3px); }

.mathbiz-sim-label {
    color: #666;
    font-size: 0.78rem;
    text-transform: uppercase;
    margin-bottom: 6px;
    letter-spacing: 0.5px;
}

.mathbiz-sim-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #333;
}

.mathbiz-sim-card-score { border-left: 4px solid #1a237e; }
.mathbiz-sim-card-score .mathbiz-sim-value { color: #1a237e; }
.mathbiz-sim-card-max { border-left: 4px solid #7986cb; }
.mathbiz-sim-card-accuracy { border-left: 4px solid #4caf50; }
.mathbiz-sim-card-streak { border-left: 4px solid #ff9800; }

.mathbiz-sim-briefing {
    background: #fff;
    border-left: 5px solid #1a237e;
    border-radius: 10px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.mathbiz-sim-topic-badge {
    display: inline-block;
    background: linear-gradient(135deg, #1a237e, #283593);
    color: white;
    padding: 4px 14px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 12px;
}

.mathbiz-sim-briefing h4 { color: #1a237e; margin: 0 0 12px 0; }

.mathbiz-sim-problem-text {
    color: #444;
    line-height: 1.7;
    font-size: 0.95rem;
}

.mathbiz-sim-formula-box {
    background: #f5f5f5;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 12px 16px;
    margin-top: 15px;
    font-family: 'Courier New', monospace;
    font-size: 0.9rem;
    color: #333;
}

.mathbiz-sim-controls {
    background: white;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.mathbiz-sim-controls h3 { color: #1a237e; margin: 0 0 20px 0; font-size: 1.2rem; }

.mathbiz-sim-input-group { margin-bottom: 20px; }

.mathbiz-sim-input-group label {
    display: block;
    font-weight: 600;
    color: #444;
    margin-bottom: 8px;
    font-size: 0.9rem;
}

.mathbiz-sim-input-row {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mathbiz-sim-unit {
    font-size: 1.2rem;
    font-weight: 700;
    color: #1a237e;
    min-width: 30px;
}

.mathbiz-sim-input-row input {
    max-width: 300px;
    font-size: 1.1rem;
    padding: 10px 15px;
}

.mathbiz-sim-hint-text {
    display: block;
    margin-top: 6px;
    color: #888;
    font-size: 0.8rem;
}

.mathbiz-sim-submit-btn {
    background: linear-gradient(135deg, #283593, #1a237e) !important;
    border: none !important;
    font-size: 1.1rem;
    padding: 12px;
    border-radius: 10px !important;
}

.mathbiz-sim-submit-btn:hover {
    background: linear-gradient(135deg, #3949ab, #283593) !important;
}

.mathbiz-sim-feedback {
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 20px;
}

.mathbiz-sim-feedback-correct {
    background: #e8f5e9;
    border-left: 5px solid #2e7d32;
}

.mathbiz-sim-feedback-partial {
    background: #fff3e0;
    border-left: 5px solid #e65100;
}

.mathbiz-sim-feedback-incorrect {
    background: #ffebee;
    border-left: 5px solid #c62828;
}

.mathbiz-sim-feedback h4 { margin: 0 0 8px 0; }
.mathbiz-sim-feedback p { margin: 0 0 5px 0; color: #444; }
.mathbiz-sim-feedback-detail { font-weight: 600; font-size: 0.9rem; }

.mathbiz-sim-charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}

.mathbiz-sim-chart-box {
    background: white;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.mathbiz-sim-chart-box h4 { color: #333; margin: 0 0 15px 0; font-size: 1rem; }
.mathbiz-sim-chart-box canvas { max-height: 280px; }

.mathbiz-sim-history {
    background: white;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.mathbiz-sim-history h4 { color: #333; margin: 0 0 15px 0; }

@media (max-width: 768px) {
    .mathbiz-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .mathbiz-sim-charts-row { grid-template-columns: 1fr; }
    .mathbiz-sim-header h1 { font-size: 1.3rem; }
    .mathbiz-sim-input-row input { max-width: 100%; }
}

