(function() {
    'use strict';

    var PROBLEMS = [
        {
            topic: 'Compound Interest',
            topicEs: 'Interes Compuesto',
            title: 'Future Value of an Investment',
            titleEs: 'Valor Futuro de una Inversion',
            description: 'You invest <strong>$10,000</strong> at <strong>6% annual interest</strong>, compounded <strong>quarterly</strong>, for <strong>5 years</strong>.<br><br>Calculate the <strong>future value</strong> of the investment.',
            descriptionEs: 'Inviertes <strong>$10,000</strong> a una <strong>tasa anual del 6%</strong>, capitalizado <strong>trimestralmente</strong>, durante <strong>5 anos</strong>.<br><br>Calcula el <strong>valor futuro</strong> de la inversion.',
            formula: 'FV = PV x (1 + r/n)^(n x t)',
            answer: 13468.55,
            maxPoints: 12,
            unit: '$',
            hint: 'r = 0.06, n = 4, t = 5. First compute (1 + 0.015)^20.',
            hintEs: 'r = 0.06, n = 4, t = 5. Primero calcula (1 + 0.015)^20.'
        },
        {
            topic: 'Loan Amortization',
            topicEs: 'Amortizacion de Prestamos',
            title: 'Monthly Mortgage Payment',
            titleEs: 'Pago Mensual de Hipoteca',
            description: 'Calculate the <strong>monthly payment</strong> on a <strong>$250,000</strong> mortgage at <strong>4.5% annual rate</strong> for <strong>30 years</strong>.',
            descriptionEs: 'Calcula el <strong>pago mensual</strong> de una hipoteca de <strong>$250,000</strong> a una <strong>tasa anual del 4.5%</strong> a <strong>30 anos</strong>.',
            formula: 'PMT = P x r x (1+r)^n / ((1+r)^n - 1), where r = annual rate / 12, n = years x 12',
            answer: 1266.71,
            maxPoints: 13,
            unit: '$',
            hint: 'r = 0.045/12 = 0.00375, n = 360. Compute (1.00375)^360 first.',
            hintEs: 'r = 0.045/12 = 0.00375, n = 360. Calcula (1.00375)^360 primero.'
        },
        {
            topic: 'Optimization (Derivatives)',
            topicEs: 'Optimizacion (Derivadas)',
            title: 'Profit Maximization',
            titleEs: 'Maximizacion de Beneficios',
            description: 'A firm has Revenue <strong>R(q) = 500q - 2q\u00b2</strong> and Cost <strong>C(q) = 1,000 + 100q</strong>.<br><br>Find the <strong>quantity q</strong> that <strong>maximizes profit</strong>.',
            descriptionEs: 'Una empresa tiene Ingresos <strong>R(q) = 500q - 2q\u00b2</strong> y Costos <strong>C(q) = 1,000 + 100q</strong>.<br><br>Encuentra la <strong>cantidad q</strong> que <strong>maximiza el beneficio</strong>.',
            formula: 'Profit P(q) = R(q) - C(q). Set dP/dq = 0 and solve for q.',
            answer: 100,
            maxPoints: 13,
            unit: 'units',
            hint: 'P(q) = -2q\u00b2 + 400q - 1000. The derivative is -4q + 400.',
            hintEs: 'P(q) = -2q\u00b2 + 400q - 1000. La derivada es -4q + 400.'
        },
        {
            topic: 'Cost Minimization',
            topicEs: 'Minimizacion de Costos',
            title: 'Optimal Production for Minimum Average Cost',
            titleEs: 'Produccion Optima para Costo Medio Minimo',
            description: 'The average cost function is <strong>AC(q) = 5,000/q + 20 + 0.5q</strong>.<br><br>Find the <strong>quantity q</strong> that <strong>minimizes average cost</strong>.',
            descriptionEs: 'La funcion de costo medio es <strong>AC(q) = 5,000/q + 20 + 0.5q</strong>.<br><br>Encuentra la <strong>cantidad q</strong> que <strong>minimiza el costo medio</strong>.',
            formula: 'Set dAC/dq = 0 and solve for q.',
            answer: 100,
            maxPoints: 13,
            unit: 'units',
            hint: 'dAC/dq = -5000/q\u00b2 + 0.5 = 0, so q\u00b2 = 10,000.',
            hintEs: 'dAC/dq = -5000/q\u00b2 + 0.5 = 0, entonces q\u00b2 = 10,000.'
        },
        {
            topic: 'Inventory Management',
            topicEs: 'Gestion de Inventarios',
            title: 'Economic Order Quantity (EOQ)',
            titleEs: 'Cantidad Economica de Pedido (EOQ)',
            description: 'A company faces <strong>annual demand D = 12,000 units</strong>, <strong>ordering cost S = $150</strong> per order, and <strong>holding cost H = $3</strong> per unit per year.<br><br>Calculate the <strong>Economic Order Quantity</strong>. Round to the nearest whole number.',
            descriptionEs: 'Una empresa tiene <strong>demanda anual D = 12,000 unidades</strong>, <strong>costo de pedido S = $150</strong> por orden, y <strong>costo de mantenimiento H = $3</strong> por unidad al ano.<br><br>Calcula la <strong>Cantidad Economica de Pedido</strong>. Redondea al entero mas cercano.',
            formula: 'EOQ = sqrt(2 x D x S / H)',
            answer: 1095,
            maxPoints: 12,
            unit: 'units',
            hint: '2 x 12,000 x 150 / 3 = 1,200,000. Find the square root.',
            hintEs: '2 x 12,000 x 150 / 3 = 1,200,000. Encuentra la raiz cuadrada.'
        },
        {
            topic: 'Break-Even Analysis',
            topicEs: 'Analisis de Punto de Equilibrio',
            title: 'Break-Even Quantity',
            titleEs: 'Cantidad de Punto de Equilibrio',
            description: 'A business has <strong>fixed costs of $50,000</strong>, a <strong>variable cost of $30 per unit</strong>, and a <strong>selling price of $80 per unit</strong>.<br><br>How many units must be sold to <strong>break even</strong>?',
            descriptionEs: 'Un negocio tiene <strong>costos fijos de $50,000</strong>, un <strong>costo variable de $30 por unidad</strong>, y un <strong>precio de venta de $80 por unidad</strong>.<br><br>Cuantas unidades deben venderse para alcanzar el <strong>punto de equilibrio</strong>?',
            formula: 'Break-Even = Fixed Costs / (Price - Variable Cost)',
            answer: 1000,
            maxPoints: 12,
            unit: 'units',
            hint: 'Contribution margin = $80 - $30 = $50 per unit.',
            hintEs: 'Margen de contribucion = $80 - $30 = $50 por unidad.'
        },
        {
            topic: 'Probability & Risk',
            topicEs: 'Probabilidad y Riesgo',
            title: 'Expected Value of a Project',
            titleEs: 'Valor Esperado de un Proyecto',
            description: 'A project has three possible outcomes:<br><strong>40% chance of $500,000 profit</strong><br><strong>35% chance of $200,000 profit</strong><br><strong>25% chance of $100,000 loss</strong><br><br>Calculate the <strong>expected value</strong>.',
            descriptionEs: 'Un proyecto tiene tres resultados posibles:<br><strong>40% probabilidad de $500,000 de ganancia</strong><br><strong>35% probabilidad de $200,000 de ganancia</strong><br><strong>25% probabilidad de $100,000 de perdida</strong><br><br>Calcula el <strong>valor esperado</strong>.',
            formula: 'EV = sum of (probability x outcome) for each scenario',
            answer: 245000,
            maxPoints: 12,
            unit: '$',
            hint: 'EV = (0.40 x 500,000) + (0.35 x 200,000) + (0.25 x -100,000).',
            hintEs: 'EV = (0.40 x 500,000) + (0.35 x 200,000) + (0.25 x -100,000).'
        },
        {
            topic: 'Integration (Consumer Surplus)',
            topicEs: 'Integracion (Excedente del Consumidor)',
            title: 'Consumer Surplus Calculation',
            titleEs: 'Calculo del Excedente del Consumidor',
            description: 'The demand curve is <strong>P = 200 - 2Q</strong> and the market price is <strong>$80</strong>.<br><br>Calculate the <strong>consumer surplus</strong>. (Hint: find the equilibrium quantity first, then integrate.)',
            descriptionEs: 'La curva de demanda es <strong>P = 200 - 2Q</strong> y el precio de mercado es <strong>$80</strong>.<br><br>Calcula el <strong>excedente del consumidor</strong>. (Pista: encuentra la cantidad de equilibrio primero, luego integra.)',
            formula: 'CS = integral from 0 to Q* of (Demand(Q) - P*) dQ, where Q* is equilibrium quantity',
            answer: 3600,
            maxPoints: 13,
            unit: '$',
            hint: 'At P = 80: Q* = (200 - 80) / 2 = 60. Then integrate (120 - 2Q) from 0 to 60.',
            hintEs: 'A P = 80: Q* = (200 - 80) / 2 = 60. Luego integra (120 - 2Q) de 0 a 60.'
        }
    ];

    class MathBizAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'MathBiz: Business Mathematics Lab';
            this.version = '1.0.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    maxPossible: 100,
                    correctCount: 0,
                    answeredCount: 0,
                    partialCount: 0,
                    streak: 0,
                    bestStreak: 0,
                    scoreHistory: [],
                    errorHistory: [],
                    pointsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    answer: 0
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, PROBLEMS.length - 1);
            var problem = PROBLEMS[idx];

            var badge = document.getElementById('topicBadge');
            if (badge) badge.textContent = problem.topic;

            var titleEl = document.getElementById('problemTitle');
            if (titleEl) titleEl.textContent = problem.title;

            var descEl = document.getElementById('problemDescription');
            if (descEl) descEl.innerHTML = problem.description;

            var formulaEl = document.getElementById('formulaBox');
            if (formulaEl) formulaEl.textContent = problem.formula;

            var unitEl = document.getElementById('unitLabel');
            if (unitEl) unitEl.textContent = problem.unit === '$' ? '$' : '';

            var answerInput = document.getElementById('answerInput');
            if (answerInput) answerInput.value = '';

            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';
        }

        validateDecisions(decisions) {
            var input = document.getElementById('answerInput');
            if (input) decisions.answer = parseFloat(input.value);

            if (isNaN(decisions.answer)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('answer_required'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var idx = Math.min(state.currentPeriod - 1, PROBLEMS.length - 1);
            var problem = PROBLEMS[idx];

            var correct = problem.answer;
            var submitted = d.answer;
            var errorPct = Math.abs(submitted - correct) / Math.abs(correct) * 100;
            var points = 0;
            var grade = 'incorrect';

            if (errorPct <= 2) {
                points = problem.maxPoints;
                grade = 'correct';
                ds.correctCount += 1;
                ds.streak += 1;
            } else if (errorPct <= 5) {
                points = Math.round(problem.maxPoints * 0.7);
                grade = 'partial';
                ds.partialCount += 1;
                ds.streak = 0;
            } else if (errorPct <= 15) {
                points = Math.round(problem.maxPoints * 0.3);
                grade = 'partial';
                ds.partialCount += 1;
                ds.streak = 0;
            } else {
                points = 0;
                grade = 'incorrect';
                ds.streak = 0;
            }

            if (ds.streak > ds.bestStreak) ds.bestStreak = ds.streak;

            ds.answeredCount = (ds.answeredCount || 0) + 1;
            ds.score += points;
            ds.scoreHistory.push(ds.score);
            ds.errorHistory.push(Math.round(errorPct * 100) / 100);
            ds.pointsHistory.push(points);

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackTitle = document.getElementById('feedbackTitle');
            var feedbackText = document.getElementById('feedbackText');
            var feedbackDetail = document.getElementById('feedbackDetail');

            if (feedbackPanel) {
                feedbackPanel.style.display = 'block';
                feedbackPanel.className = 'mathbiz-sim-feedback mathbiz-sim-feedback-' + grade;

                if (grade === 'correct') {
                    if (feedbackTitle) feedbackTitle.textContent = '\u2705 ' + window.mySimulation.t('feedback_correct');
                    if (feedbackText) feedbackText.textContent = window.mySimulation.t('feedback_perfect');
                } else if (grade === 'partial') {
                    if (feedbackTitle) feedbackTitle.textContent = '\u26a0\ufe0f ' + window.mySimulation.t('feedback_partial');
                    if (feedbackText) feedbackText.innerHTML = window.mySimulation.t('feedback_close') + '<br>' + problem.hint;
                } else {
                    if (feedbackTitle) feedbackTitle.textContent = '\u274c ' + window.mySimulation.t('feedback_incorrect');
                    if (feedbackText) feedbackText.innerHTML = window.mySimulation.t('feedback_review') + '<br>' + problem.hint;
                }

                if (feedbackDetail) {
                    var detailText = window.mySimulation.t('feedback_your_answer') + ': ';
                    if (problem.unit === '$') detailText += '$' + submitted.toLocaleString();
                    else detailText += submitted.toLocaleString() + ' ' + problem.unit;
                    detailText += ' | ' + window.mySimulation.t('feedback_correct_answer') + ': ';
                    if (problem.unit === '$') detailText += '$' + correct.toLocaleString();
                    else detailText += correct.toLocaleString() + ' ' + problem.unit;
                    detailText += ' | ' + window.mySimulation.t('feedback_points') + ': ' + points + '/' + problem.maxPoints;
                    feedbackDetail.textContent = detailText;
                }
            }

            var isLast = state.currentPeriod >= PROBLEMS.length; var submitBtn = document.getElementById('nextPeriodBtn'); var nextBtn = document.getElementById('nextProblemBtn'); var ansInput = document.getElementById('answerInput'); if (nextBtn && !isLast) { if (ansInput) ansInput.disabled = true; if (submitBtn) submitBtn.style.display = 'none'; nextBtn.style.display = 'block'; }

            return {
                period: state.currentPeriod,
                topic: problem.topic,
                submitted: submitted,
                correct: correct,
                errorPct: Math.round(errorPct * 100) / 100,
                points: points,
                maxPoints: problem.maxPoints,
                grade: grade,
                cumulativeScore: ds.score
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score');
            uiManager.bind('maxScoreDisplay', 'domainState.maxPossible');
            uiManager.bind('accuracyDisplay', 'domainState.correctCount', function(v) {
                var st = window.mySimulation ? window.mySimulation.state : null;
                var total = st && st.domainState ? (st.domainState.answeredCount || 0) : 0;
                if (total <= 0) return '0%';
                return Math.round((v / total) * 100) + '%';
            });
            uiManager.bind('streakDisplay', 'domainState.streak');
            var self = this; var submitBtn = document.getElementById('nextPeriodBtn'); var nextBtn = document.getElementById('nextProblemBtn'); if (submitBtn && !nextBtn) { nextBtn = document.createElement('button'); nextBtn.id = 'nextProblemBtn'; nextBtn.className = 'btn btn-success btn-lg btn-block mt-2'; nextBtn.style.display = 'none'; var lbl = window.mySimulation ? window.mySimulation.t('next_problem_btn') : 'Next Problem'; nextBtn.textContent = (lbl === 'next_problem_btn') ? 'Next Problem' : lbl; submitBtn.parentNode.insertBefore(nextBtn, submitBtn.nextSibling); } if (nextBtn && !nextBtn._mbWired) { nextBtn._mbWired = true; nextBtn.addEventListener('click', function() { self._updateBriefing(window.mySimulation.state); nextBtn.style.display = 'none'; if (submitBtn) submitBtn.style.display = 'block'; var ansInput = document.getElementById('answerInput'); if (ansInput) { ansInput.disabled = false; ansInput.focus(); } }); }
        }

        formatCompletionMessage(summary) { var t = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; }; var s = summary || {}; var pct = (s.percentage != null) ? s.percentage : 0; var perf = s.performance || ''; var insights = (s.insights || []).map(function(i) { return `<li>${i}</li>`; }).join(''); var pts = ((s.totalPoints != null) ? s.totalPoints : 0) + ' / ' + ((s.maxPoints != null) ? s.maxPoints : 0); var exact = ((s.correctCount != null) ? s.correctCount : 0) + ' / ' + PROBLEMS.length; var rec = insights ? `<hr><div style='text-align:left'><strong>${t('complete_recommendations')}</strong><ul>${insights}</ul></div>` : ''; return `<div style='text-align:center;padding:12px'><div style='font-size:2.6rem;font-weight:800;color:#1a237e'>${pct}%</div><div style='text-transform:uppercase;letter-spacing:.5px;font-size:.8rem;color:#888;margin-bottom:12px'>${t('complete_score')}</div><div style='margin-bottom:12px'><span class='badge badge-primary' style='font-size:1rem;padding:8px 16px'>${perf}</span></div><p style='font-size:1.1rem;margin-bottom:4px'>${pts} ${t('complete_points')}</p><p style='color:#888;margin-bottom:12px'>${exact} ${t('complete_exact')}</p>${rec}</div>`; }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Cumulative Score',
                            data: [],
                            borderColor: '#1a237e',
                            backgroundColor: 'rgba(26,35,126,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score Progress' },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Points' } }
                        }
                    }
                },
                errorChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Error %',
                            data: [],
                            backgroundColor: function(ctx) {
                                var val = ctx.raw || 0;
                                if (val <= 2) return 'rgba(76,175,80,0.7)';
                                if (val <= 5) return 'rgba(255,152,0,0.7)';
                                return 'rgba(244,67,54,0.7)';
                            },
                            borderColor: function(ctx) {
                                var val = ctx.raw || 0;
                                if (val <= 2) return '#2e7d32';
                                if (val <= 5) return '#e65100';
                                return '#c62828';
                            },
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Answer Accuracy (Error %)' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, title: { display: true, text: 'Error %' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.scoreHistory.map(function(_, i) { return 'P' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: ds.scoreHistory }]
                },
                errorChart: {
                    labels: labels,
                    datasets: [{ data: ds.errorHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history || history.length === 0) return {};

            var totalPoints = 0;
            var maxPoints = 0;
            var correctCount = 0;

            history.forEach(function(h) {
                if (h.results) {
                    totalPoints += h.results.points || 0;
                    maxPoints += h.results.maxPoints || 0;
                    if (h.results.grade === 'correct') correctCount += 1;
                }
            });

            var pct = maxPoints > 0 ? (totalPoints / maxPoints) * 100 : 0;
            var performance = 'Needs Practice';
            if (pct >= 90) performance = 'Excellent';
            else if (pct >= 75) performance = 'Good';
            else if (pct >= 60) performance = 'Satisfactory';

            var insights = [];
            if (pct >= 90) {
                insights.push('Outstanding mastery of business mathematics. Ready for advanced quantitative courses.');
            } else if (pct >= 75) {
                insights.push('Solid foundation in business math. Review the problems where errors exceeded 5%.');
            } else if (pct >= 60) {
                insights.push('Adequate understanding, but further practice with derivatives and integration is recommended.');
            } else {
                insights.push('Significant gaps remain. Focus on building computational fluency through repeated practice.');
            }

            var weakTopics = [];
            history.forEach(function(h) {
                if (h.results && h.results.errorPct > 15) {
                    weakTopics.push(h.results.topic);
                }
            });
            if (weakTopics.length > 0) {
                insights.push('Topics requiring review: ' + weakTopics.join(', ') + '.');
            }

            return {
                totalPoints: totalPoints,
                maxPoints: maxPoints,
                percentage: Math.round(pct),
                correctCount: correctCount,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.grade === 'incorrect') {
                return window.mySimulation.t('hint_review');
            }
            if (results.grade === 'partial') {
                return window.mySimulation.t('hint_close');
            }
            if (results.grade === 'correct' && state.domainState.streak >= 3) {
                return window.mySimulation.t('hint_streak');
            }
            return null;
        }

